def compare_one(a, b):
    def to_numeric(val):
        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            return float(val.replace(",", "."))
        return float(val)

    num_a, num_b = to_numeric(a), to_numeric(b)

    if num_a == num_b:
        return None
    return a if num_a > num_b else b
